      + '#analysisView .mlsrvu-note,#analysisView .mlsrvu-foot{color:#46586f!important}'
      + '#analysisView .mlsrvu-kpi .l{color:#46586f!important}'
      + '#analysisView h2{color:#1E2B24!important;letter-spacing:-.2px}'
