          var ld = x.appt_date || ''; if (!ld) { try { var dd = new Date(x.start_at); ld = ymd(dd); } catch (e) {} }
          map[apptKey(x.name, ld, lt)] = 1;
          map['D:' + String(x.name || '').trim().toLowerCase().replace(/\s+/g, ' ') + '|' + ld] = 1;
          var nt = String(x.name || '').trim().toLowerCase().split(/\s+/);
