    if ((b = $('ez3sPrep'))) b.onclick = openPrep;
    [].slice.call(wrap().querySelectorAll('#ez3Seg button[data-r]')).forEach(function (el) {
      el.onclick = function () { S.staffRange = el.getAttribute('data-r'); S.showCount = 5; render(); };
    });
