/* feat_copilot_draft — one-tap "draft on command" quick-actions in the Copilot (item #2, 2026-07-03).
   Additive + safe: adds draft chips next to the Copilot's existing quick chips. Clicking one drops a
   strong drafting prompt (for the ACTIVE patient) into the Copilot input and sends it — using the
   Copilot's existing send path + patient context. No fetch wrapping, no data changes. */
(function(){
  "use strict";
  if(window.__mlsCopilotDraft) return; window.__mlsCopilotDraft=true;

  function activeName(){
    try{ var ap=window.activePatient; if(typeof ap==='function') ap=ap(); return (ap&&ap.name)?ap.name:null; }catch(e){ return null; }
  }

  /* b243 (owner P1 "chips don't draft"): the op-note and AVS chips now invoke the
     REAL native workflows (op-prep modal w/ templates+fill box; the AVS module via
     its real button) instead of sending a generic prompt into the chat — the chat
     answer was the "glitchy empty panel does nothing" experience. Referral letter
     keeps the prompt route (no native flow exists for it yet). */
  var DRAFTS = [
    { label:'✍️ Draft op note', native:function(){ try{ if(typeof window.openOpPrepForPatient==='function'){ window.openOpPrepForPatient(); return true; } }catch(e){} return false; }, prompt:function(n){ return 'Draft a complete operative note for '+(n||'the active patient')+' for their planned/most recent procedure. Use standard operative-note structure: Preoperative diagnosis, Postoperative diagnosis, Procedure, Surgeon, Assistant, Anesthesia, Indications, Findings, Technique (numbered operative steps), Implants/Instrumentation, Estimated blood loss, Complications, Specimens, Disposition. Pull the procedure and clinical details from this patient’s record; wherever a specific detail is not documented, insert a clearly-marked [fill in] placeholder rather than inventing it.'; } },
    { label:'✍️ After-visit summary', native:function(){ try{
        var ab=document.getElementById('mlsavsBtn'); if(ab){ ab.click(); return true; }
        /* the real AVS button lives in the visit workspace — reveal it first,
           then click (the proven b235 quick-chip pattern, same 800ms) */
        var adv=document.getElementById('ez3Adv');
        if(adv && document.body && !document.body.classList.contains('ez3adv')){
          adv.click();
          setTimeout(function(){ try{ var b2=document.getElementById('mlsavsBtn'); if(b2) b2.click(); else if(typeof window.toast==='function') window.toast('After-visit summary is not available on this build.','err'); }catch(e){} }, 800);
          return true;
        }
      }catch(e){} return false; }, prompt:function(n){ return 'Write a clear, patient-friendly after-visit summary for '+(n||'the active patient')+' based on their record and today’s visit: what we discussed, any diagnosis in plain language, medication changes, instructions/precautions, and next steps / follow-up. Warm, plain English, no jargon.'; } },
    { label:'✍️ Referral letter', prompt:function(n){ return 'Draft a referral letter to physical therapy for '+(n||'the active patient')+' based on their spine/pain diagnoses and history. Include the referring diagnosis with ICD-10 if known, brief relevant history and exam, precautions, and specific PT goals/frequency. Professional letter format.'; } }
  ];

  function sendPrompt(text){
    try{
      if(typeof window.openCopilotDock==='function') window.openCopilotDock();
      var input=document.getElementById('copilotInput');
      var send=document.getElementById('copilotSendBtn');
      if(!input||!send) return;
      var set=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(input),'value');
      if(set&&set.set) set.set.call(input,text); else input.value=text;
      input.dispatchEvent(new Event('input',{bubbles:true}));
      setTimeout(function(){ try{ send.click(); }catch(e){} }, 60);
    }catch(e){}
  }

  function inject(){
    try{
      var wrap=document.getElementById('copilotChips');
      if(!wrap) return;
      // only add once the app's own chips are present (dock open) and ours aren't
      if(wrap.children.length===0) return;
      if(wrap.querySelector('[data-mlsdraft]')) return;
      var model=wrap.children[0]; // clone an existing chip for native styling
      var n=activeName();
      DRAFTS.forEach(function(d){
        var chip;
        /* cvd-1.0.0: the clone carried the model chip's INLINE
           onclick="copilotChip(this)" — only `id` was stripped. That handler is
           registered at clone time, so it ran FIRST and asked Copilot the chip's
           own label ("✍️ Draft op note") while stopPropagation (not
           stopImmediatePropagation) failed to cancel it. The real prompt then
           arrived 60ms later into `if(_copilotBusy) return` and was swallowed.
           The doctor got an answer to the button's caption. */
        if(model && model.cloneNode){ chip=model.cloneNode(true); chip.removeAttribute('id'); chip.removeAttribute('onclick'); chip.onclick=null; chip.textContent=d.label; }
        else { chip=document.createElement('button'); chip.textContent=d.label; chip.style.cssText='font-size:12.5px;border:1px solid #cfe0f3;background:#fff;color:#204034;border-radius:999px;padding:6px 11px;cursor:pointer;margin:3px'; }
        chip.setAttribute('data-mlsdraft','1');
        chip.addEventListener('click', function(ev){ ev.preventDefault(); ev.stopImmediatePropagation(); if(d.native && d.native()) return; sendPrompt(d.prompt(activeName())); }, true);
        wrap.appendChild(chip);
      });
    }catch(e){}
  }

  try{ var _ijRaf=0; new MutationObserver(function(){ if(_ijRaf) return; _ijRaf=1; (window.requestAnimationFrame||function(f){return setTimeout(f,50);})(function(){ _ijRaf=0; inject(); }); }).observe(document.documentElement,{childList:true,subtree:true}); }catch(e){}
  var draftChipIv = setInterval(inject, 6000);
  if(document.readyState!=='loading') inject(); else document.addEventListener('DOMContentLoaded', inject);
})();


/* feat_delall_guard — strong "type DELETE" confirmation on the Delete-ALL-templates button (item 18, 2026-07-03).
   Intercepts clicks on the delete-all-templates control, blocks the immediate wipe, and requires the user to
   type DELETE. Only then does it clear via the app's own setTemplates([]) + renderTemplateList(). Protects the
   doctor's uploaded templates from an accidental one-click wipe. */
(function(){
  "use strict";
  if(window.__mlsDelGuard) return; window.__mlsDelGuard=true;

  function isDelAll(el){
    var n=0;
    while(el && el.nodeType===1 && n<5){
      if(el.id==='mlsP1DelAll') return el;
      if(el.tagName==='BUTTON'){
        var t=(el.textContent||'').toLowerCase();
        if(t.indexOf('delete')>=0 && t.indexOf('template')>=0 && (t.indexOf('all')>=0 || t.indexOf('every')>=0)) return el;
      }
      el=el.parentElement; n++;
    }
    return null;
  }

  document.addEventListener('click', function(e){
    var btn=isDelAll(e.target);
    if(!btn) return;
    e.preventDefault(); e.stopImmediatePropagation();
    openModal();
  }, true);

  function count(){ try{ return (typeof window.getTemplates==='function') ? (window.getTemplates()||[]).length : null; }catch(e){ return null; } }

  function doDelete(){
    var ok=false;
    try{ if(typeof window.setTemplates==='function'){ window.setTemplates([]); ok=true; } }catch(e){}
    try{ if(typeof window.renderTemplateList==='function') window.renderTemplateList(); }catch(e){}
    // verify + last-resort fallback on the known storage keys (per-user + shared)
    var left=count();
    if(left && left>0){
      try{
        localStorage.removeItem('mls_playbooks');
        for(var i=localStorage.length-1;i>=0;i--){ var k=localStorage.key(i); if(k && /::templates$/.test(k)) localStorage.removeItem(k); }
        if(typeof window.renderTemplateList==='function') window.renderTemplateList();
        ok=true;
      }catch(e){}
    }
    return count()===0 || ok;
  }

  function openModal(){
    if(document.getElementById('mlsDelBack')) return;
    var n=count();
    var back=document.createElement('div');
    back.id='mlsDelBack';
    back.style.cssText='position:fixed;inset:0;background:rgba(10,30,60,.5);z-index:2147483000;display:flex;align-items:center;justify-content:center;padding:16px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif';
    var box=document.createElement('div');
    box.style.cssText='background:#fff;border-radius:16px;max-width:430px;width:100%;padding:22px;box-shadow:0 12px 44px rgba(0,0,0,.32)';
    box.innerHTML=''
      +'<div style="font-weight:800;font-size:17px;color:#a12626;margin-bottom:6px">🗑 Delete all templates?</div>'
      +'<div style="font-size:13.5px;color:#5b6b7c;margin-bottom:14px">This permanently removes <b>'+(n==null?'all':n)+'</b> template'+(n===1?'':'s')+'. This cannot be undone. Type <b>DELETE</b> to confirm.</div>'
      +'<input id="mlsDelInput" type="text" placeholder="Type DELETE" autocomplete="off" style="width:100%;padding:11px 12px;border:1px solid #E7E5DD;border-radius:10px;font-size:15px;box-sizing:border-box;letter-spacing:1px" />'
      +'<div id="mlsDelMsg" style="font-size:13px;margin-top:12px;display:none;color:#0f6b49"></div>'
      +'<div style="display:flex;gap:8px;margin-top:18px">'
      +'  <button id="mlsDelCancel" type="button" style="flex:1;padding:11px;border:1px solid #E7E5DD;background:#eef4fc;color:#204034;border-radius:10px;font-weight:700;cursor:pointer">Cancel</button>'
      +'  <button id="mlsDelGo" type="button" disabled style="flex:1;padding:11px;border:none;background:#d9534f;color:#fff;border-radius:10px;font-weight:700;cursor:pointer;opacity:.5">Delete all</button>'
      +'</div>';
    back.appendChild(box); document.body.appendChild(back);
    var input=box.querySelector('#mlsDelInput');
    var go=box.querySelector('#mlsDelGo');
    var msg=box.querySelector('#mlsDelMsg');
    function close(){ var b=document.getElementById('mlsDelBack'); if(b) b.remove(); }
    input.addEventListener('input', function(){
      var ok=input.value.trim().toUpperCase()==='DELETE';
      go.disabled=!ok; go.style.opacity=ok?'1':'.5';
    });
    box.querySelector('#mlsDelCancel').onclick=close;
    back.addEventListener('click', function(e){ if(e.target===back) close(); });
    go.onclick=function(){
      if(input.value.trim().toUpperCase()!=='DELETE') return;
      go.disabled=true; go.textContent='Deleting…';
      var ok=doDelete();
      msg.style.display='block';
      if(ok){ msg.style.color='#0f6b49'; msg.textContent='✓ All templates deleted.'; setTimeout(close,1400); }
      else { msg.style.color='#a12626'; msg.textContent='Could not delete — please try again.'; go.disabled=false; go.textContent='Delete all'; }
    };
    setTimeout(function(){ try{ input.focus(); }catch(e){} }, 50);
  }
})();


/* feat_upload_templates — easy "Upload templates" button by the Prep-op-note action (item 14, 2026-07-02).
   Additive + safe: it only opens the app's EXISTING multi-file template picker (#tplMultiFileInput),
   so the app's own upload/processing handler runs. No data is deleted or changed. */
(function(){
  "use strict";
  if(window.__mlsUplTpl) return; window.__mlsUplTpl=true;

  function trigger(){
    var i=document.getElementById('tplMultiFileInput')||document.getElementById('tplFileInput');
    if(i){ try{ i.click(); }catch(e){} }
    else { (window.toast||window.alert)('Open the Templates section to upload your templates.','err'); }
  }

  function makeBtn(){
    var b=document.createElement('button');
    b.type='button'; b.id='mlsUplTplBtn';
    b.textContent='📤 Upload templates';
    b.title='Add your own note templates (pick multiple files at once)';
    b.style.cssText='margin:10px 0 2px;display:inline-flex;align-items:center;gap:6px;background:#eef4fc;border:1px solid #cfe0f3;color:#204034;border-radius:10px;padding:8px 13px;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;line-height:1.2';
    b.addEventListener('mouseenter',function(){ b.style.background='#e2edfa'; });
    b.addEventListener('mouseleave',function(){ b.style.background='#eef4fc'; });
    b.addEventListener('click',function(e){ e.preventDefault(); e.stopPropagation(); trigger(); });
    return b;
  }

  function findAnchor(){
    var els=document.querySelectorAll('button, a, div');
    for(var i=0;i<els.length;i++){
      var t=(els[i].innerText||'').trim();
      if(t && t.length<70 && /prep op note/i.test(t)) return els[i];
    }
    return null;
  }

  function inject(){
    try{
      if(document.getElementById('mlsUplTplBtn')) return;
      var anchor=findAnchor();
      if(!anchor) return;
      // climb to a card-sized ancestor so the button sits under the whole quick-action card
      var card=anchor;
      for(var k=0;k<3 && card.parentElement;k++){
        if(card.getBoundingClientRect().height>44) break;
        card=card.parentElement;
      }
      if(!card.parentNode) return;
      card.parentNode.insertBefore(makeBtn(), card.nextSibling);
    }catch(e){}
  }

  try{ var _ijRaf=0; new MutationObserver(function(){ if(_ijRaf) return; _ijRaf=1; (window.requestAnimationFrame||function(f){return setTimeout(f,50);})(function(){ _ijRaf=0; inject(); }); }).observe(document.documentElement,{childList:true,subtree:true}); }catch(e){}
  var uplBtnIv = setInterval(inject, 6000);
  if(document.readyState!=='loading') inject(); else document.addEventListener('DOMContentLoaded', inject);
})();


/* feat_docselect_merge — MLS Easy: consolidate the doctor controls into ONE clean pill (2026-07-02).
   Before: a "Pulling as: [doctor] v" chip PLUS a separate "Find Doctors" button = clutter.
   After: one pill — the chip keeps its native provider dropdown, and a small "+ find a doctor"
   is folded INSIDE it (proxies the original Find Doctors, which stays functional but hidden).
   Pure DOM/CSS + click-proxy; never reimplements provider switching, so the Athena pull is safe. */
(function(){
  "use strict";
  if(window.__mlsDocMerge) return; window.__mlsDocMerge=true;

  function apply(){
    try{
      var chip=document.getElementById('mlsProvChip');
      var find=document.getElementById('mlsFindDocBtn');
      if(!chip) return;

      // Keep the real Find Doctors button in the DOM (its picker still works when clicked
      // programmatically) but hide it so there's only one visible control.
      if(find && find.style.display!=='none'){ find.style.display='none'; }

      // Make the chip read as one tidy pill.
      try{
        chip.style.display='inline-flex';
        chip.style.alignItems='center';
        chip.style.gap='2px';
        chip.style.cursor='pointer';
      }catch(e){}

      // Fold a compact "find a doctor" affordance INSIDE the chip (once).
      if(!chip.querySelector('#mlsFindInline')){
        var sep=document.createElement('span');
        sep.id='mlsFindInlineSep';
        sep.textContent='·';
        sep.style.cssText='margin:0 4px 0 8px;color:#C9DCD2';
        var b=document.createElement('span');
        b.id='mlsFindInline';
        b.textContent='🔍 find a doctor';
        b.title='Search all doctors in the practice';
        b.setAttribute('role','button');
        b.style.cssText='color:#2E6A4B;font-weight:700;font-size:12px;cursor:pointer;white-space:nowrap';
        b.addEventListener('click',function(e){
          e.preventDefault(); e.stopPropagation();
          var f=document.getElementById('mlsFindDocBtn');
          if(f){ try{ f.style.display=''; }catch(_){}
                 f.click();
                 try{ f.style.display='none'; }catch(_){}
          }
        });
        chip.appendChild(sep);
        chip.appendChild(b);
      }
    }catch(e){}
  }

  try{ new MutationObserver(apply).observe(document.documentElement,{childList:true,subtree:true}); }catch(e){}
  var mergeIv = setInterval(apply, 1500);
  if(document.readyState!=='loading') apply(); else document.addEventListener('DOMContentLoaded', apply);
})();


/* feat_portal_invite — doctor "Send portal login" button on the active patient (2026-07-02).
   Self-contained IIFE. Adds a pill button next to the active-patient chip; clicking opens a
   small in-app popup to email the patient a one-time secure portal login. Reuses the app's
   own MLS session token (localStorage sf_bk_token). No page navigation. */
(function(){
  "use strict";
  if(window.__mlsPortalInvite) return; window.__mlsPortalInvite=true;
  var API="https://scrivara-backend.onrender.com";

  function tok(){ try{ return localStorage.getItem('sf_bk_token'); }catch(e){ return null; } }
  function cleanId(v){
    var s=(v==null?'':String(v)).trim();
    return (!s || /^(?:undefined|null)$/i.test(s)) ? '' : s;
  }
  function cleanName(v){
    var s=(v==null?'':String(v)).replace(/\s+/g,' ').trim().toLowerCase();
    return (!s || /^(?:undefined|null)$/i.test(s)) ? '' : s;
  }
  function cleanDob(v){
    var raw=(v==null?'':String(v)).trim(), m;
    if((m=raw.match(/^(\d{4})[-\/]?(\d{2})[-\/]?(\d{2})(?:\D|$)/))){
      raw=m[1]+m[2]+m[3];
    }else if((m=raw.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})$/))){
      raw=m[3]+('0'+m[1]).slice(-2)+('0'+m[2]).slice(-2);
    }else{
      raw=raw.replace(/\D/g,'');
      if(/^\d{8}$/.test(raw) && !/^(?:18|19|20|21)/.test(raw)) raw=raw.slice(4)+raw.slice(0,4);
    }
    if(!/^\d{8}$/.test(raw)) return '';
    var y=Number(raw.slice(0,4)), mo=Number(raw.slice(4,6)), d=Number(raw.slice(6,8));
    var dt=new Date(Date.UTC(y,mo-1,d));
    return (dt.getUTCFullYear()===y && dt.getUTCMonth()===mo-1 && dt.getUTCDate()===d) ? raw : '';
  }
  function stableRefs(ap){
    if(!ap || typeof ap!=='object') return [];
    var out=[];
    [['id',ap.id],['athenaId',ap.athenaId],['mrn',ap.mrn]].forEach(function(pair){
      var s=cleanId(pair[1]);
      if(s && !out.some(function(ref){ return ref.namespace===pair[0] && ref.value===s; })) out.push({namespace:pair[0],value:s});
    });
    return out;
  }
  function refsIntersect(a,b){
    for(var i=0;i<a.length;i++) for(var j=0;j<b.length;j++){
      if(a[i].namespace===b[j].namespace && a[i].value===b[j].value) return true;
    }
    return false;
  }
  function demographicKey(ap){
    var nm=cleanName(ap&&ap.name), dob=cleanDob(ap&&ap.dob);
    return (nm && dob) ? (nm+'|'+dob) : '';
  }
  function patientIdentity(ap){
    if(!ap || typeof ap!=='object') return null;
    var refs=stableRefs(ap), demo=demographicKey(ap);
    if(refs.length) return { key:'ref:'+refs[0].namespace+':'+refs[0].value, externalId:refs[0].value, externalIdType:refs[0].namespace, stableRefs:refs, demoKey:demo, hasStable:true };
    if(demo) return { key:'demo:'+demo, externalId:'demo:'+demo, externalIdType:'demographic', stableRefs:[], demoKey:demo, hasStable:false };
    return null;
  }
  function samePatientIdentity(a,b){
    var left=patientIdentity(a), right=patientIdentity(b);
    if(!left || !right) return false;
    if(left.hasStable || right.hasStable){
      return left.hasStable && right.hasStable && refsIntersect(left.stableRefs,right.stableRefs);
    }
    return left.key===right.key;
  }
  function patientList(){
    try{ var list=(typeof window.getPatients==='function')?window.getPatients():null; return Array.isArray(list)?list:null; }catch(e){ return null; }
  }
  function uniqueDemographicFallback(ap){
    var key=demographicKey(ap), list=patientList();
    if(!key || !list) return false;
    return list.filter(function(p){ return p && demographicKey(p)===key; }).length===1;
  }
  function active(){
    try{
      var ap=window.activePatient;
      if(typeof ap==='function') ap=ap();
      var proof=patientIdentity(ap);
      if(!proof) return null;
      /* A name-only/partial placeholder is never a patient identity. The
         demographic fallback is accepted only when an exact nonblank name+DOB
         identifies one and only one stored record. */
      if(!proof.hasStable && !uniqueDemographicFallback(ap)) return null;
      return ap;
    }catch(e){ return null; }
  }
  function patientKey(ap){
    var proof=patientIdentity(ap);
    return proof ? proof.key : '';
  }
  function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
  function findEmail(ap){
    try{
      var proof=patientIdentity(ap);
      if(!proof || (!proof.hasStable && !uniqueDemographicFallback(ap))) return '';
      var own=String((ap&&ap.email)||'').trim();
      if(own) return own;
      var list=patientList(); if(!list) return '';
      var matches=[];
      if(proof.hasStable){
        matches=list.filter(function(p){
          return refsIntersect(proof.stableRefs,stableRefs(p));
        });
      }
      /* A list representation can legitimately omit the stable ID. Only use
         demographics when the exact pair has a single match; undefined IDs
         are never compared and therefore can never make the first row win. */
      if(!matches.length && proof.demoKey){
        var byDemo=list.filter(function(p){ return p && demographicKey(p)===proof.demoKey; });
        /* A stable-ID patient can fall back only to an ID-less representation.
           A same-demographic record with another stable ID is a different
           patient, even when the raw number happens to match another field. */
        if(proof.hasStable && byDemo.some(function(p){ return stableRefs(p).length>0; })) return '';
        matches=byDemo;
      }
      if(matches.length!==1) return '';
      return String((matches[0]&&matches[0].email)||'').trim();
    }catch(e){}
    return '';
  }

  /* Return only the one stored record that exactly represents the reviewed
     patient. This uses the same namespace-aware identity rules as the send
     guard; equal raw values in different ID namespaces never match. */
  function storedPatient(ap){
    try{
      var list=patientList();
      if(!list) return null;
      var matches=list.filter(function(p){ return p&&samePatientIdentity(p,ap); });
      return matches.length===1?matches[0]:null;
    }catch(e){ return null; }
  }
  function portalChartData(ap,email){
    var src=storedPatient(ap), data={}, k;
    if(src&&typeof src==='object') for(k in src){ if(Object.prototype.hasOwnProperty.call(src,k)) data[k]=src[k]; }
    data.id=ap.externalId;
    data.name=ap.name||data.name||'';
    data.dob=ap.dob||data.dob||'';
    data.mrn=ap.mrn||data.mrn||'';
    data.email=email;
    return data;
  }
  function jsonResponse(r){
    return r.json().catch(function(){return {};}).then(function(j){ return {ok:r.ok,status:r.status,j:j}; });
  }
  function invitePatient(body,tk){
    return fetch(API+'/api/patient/admin/send-portal-invite',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+tk},body:JSON.stringify(body)}).then(jsonResponse);
  }
  function syncPortalChart(ap,email,tk){
    var data=portalChartData(ap,email);
    return fetch(API+'/api/patients',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+tk},body:JSON.stringify({external_id:ap.externalId,label:'',data:data})}).then(jsonResponse);
  }

  function openModal(ap){
    if(document.getElementById('mlsPiBack')) return;
    var proof=patientIdentity(ap);
    if(!proof || (!proof.hasStable && !uniqueDemographicFallback(ap))) return;
    /* Freeze the reviewed patient. Even if the app reuses/mutates its active
       patient object, the eventual explicit send keeps this exact identity. */
    var email=findEmail(ap);
    ap={
      id:cleanId(ap&&ap.id), athenaId:cleanId(ap&&ap.athenaId), mrn:cleanId(ap&&ap.mrn),
      name:(ap&&ap.name)||'', dob:(ap&&ap.dob)||'', email:email,
      externalId:proof.externalId, patientKey:proof.key
    };
    var nm=ap.name||'this patient';
    var back=document.createElement('div');
    back.id='mlsPiBack';
    back.style.cssText='position:fixed;inset:0;background:rgba(10,30,60,.45);z-index:2147483000;display:flex;align-items:center;justify-content:center;padding:16px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif';
    var box=document.createElement('div');
    box.style.cssText='background:#fff;border-radius:16px;max-width:420px;width:100%;padding:22px;box-shadow:0 12px 44px rgba(0,0,0,.32)';
    box.innerHTML=''
      +'<div style="font-weight:800;font-size:17px;color:#204034;margin-bottom:4px">📧 Send portal login</div>'
      +'<div style="font-size:13.5px;color:#5b6b7c;margin-bottom:14px">'+esc(nm)+' will get a secure email with a one-time link to view their records and ask questions about their care.</div>'
      +'<label style="display:block;font-size:12.5px;font-weight:700;color:#204034;margin-bottom:5px">Patient email</label>'
      +'<input id="mlsPiEmail" type="email" value="'+esc(email)+'" placeholder="patient@email.com" style="width:100%;padding:11px 12px;border:1px solid #E7E5DD;border-radius:10px;font-size:15px;box-sizing:border-box;color:#0d2338" />'
      +'<div id="mlsPiMsg" style="font-size:13px;margin-top:12px;display:none"></div>'
      +'<div style="display:flex;gap:8px;margin-top:18px">'
      +'  <button id="mlsPiCancel" type="button" style="flex:1;padding:11px;border:1px solid #E7E5DD;background:#eef4fc;color:#204034;border-radius:10px;font-weight:700;cursor:pointer">Cancel</button>'
      +'  <button id="mlsPiSend" type="button" style="flex:2;padding:11px;border:none;background:#2E6A4B;color:#fff;border-radius:10px;font-weight:700;cursor:pointer">Send login</button>'
      +'</div>';
    back.appendChild(box); document.body.appendChild(back);
    var msg=box.querySelector('#mlsPiMsg');
    function showMsg(t,ok){ msg.style.display='block'; msg.textContent=t; msg.style.color=ok?'#0f6b49':'#a12626'; }
    function close(){ var b=document.getElementById('mlsPiBack'); if(b) b.remove(); }
    box.querySelector('#mlsPiCancel').onclick=close;
    back.addEventListener('click',function(e){ if(e.target===back) close(); });
    box.querySelector('#mlsPiSend').onclick=function(){
      var em=(box.querySelector('#mlsPiEmail').value||'').trim();
      if(em && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)){
        showMsg('Please enter a valid patient email address.',false);
        return;
      }
      if(!em){ showMsg('Please enter the patient’s email.',false); return; }
      /* Keep the invite bound to the patient for whom this modal opened. A
         background/patient switch must never turn a stale dialog into a send
         for the wrong chart. */
      var now=active();
      if(!now || !ap.patientKey || !samePatientIdentity(now,ap)){
        showMsg('The active patient changed. Close this window and open Patient portal again.',false);
        return;
      }
      var tk=tok();
      if(!tk){ showMsg('You’re signed out — sign back into MLS and try again.',false); return; }
      var btn=box.querySelector('#mlsPiSend'); btn.disabled=true; var old=btn.textContent; btn.textContent='Sending…';
      var body={ email:em, name:ap.name, dob:ap.dob, external_id:ap.externalId, mrn:ap.mrn };
      invitePatient(body,tk)
        .then(function(res){
          /* Patient saves mirror to the cloud best-effort. If that background
             request was still in flight (or failed while offline), the invite
             endpoint correctly returns 404 because no chart exists. Repair
             this one exact frozen chart, then retry the invite exactly once. */
          if(res.status!==404) return res;
          btn.textContent='Saving patient...';
          return syncPortalChart(ap,em,tk).then(function(saved){
            if(!saved.ok) return {ok:false,status:saved.status,j:saved.j,chartSync:true};
            btn.textContent='Sending...';
            return invitePatient(body,tk);
          });
        })
        .then(function(res){
          if(res.ok && res.j && res.j.sent===false){
            showMsg('Portal access was created, but the email could not be sent. Ask your MLS admin to check the mail service, then resend.',false);
          }
          else if(res.ok){ showMsg('✓ Portal login sent to '+em+'.',true); setTimeout(close,1900); }
          else if(res.chartSync && res.status===402){ showMsg('Patient portal invites require active MLS access. Enter an access code or ask the account owner to activate this login.',false); }
          else if(res.chartSync){ showMsg((res.j&&(res.j.message||res.j.error))||'The selected patient could not be saved to your MLS cloud. Try again shortly.',false); }
          else if(res.status===401||res.status===403){ showMsg('This account isn’t authorized to send invites (needs admin). Ask the owner to send it.',false); }
          else if(res.status===409){ showMsg((res.j&&res.j.error)||'A portal account already exists for this patient or email.',false); }
          else if(res.status===502){ showMsg('The invite was created, but the email service could not send it. Try again shortly or ask your MLS admin to check mail setup.',false); }
          else { showMsg((res.j&&(res.j.error||res.j.message))||('Could not send (error '+res.status+').'),false); }
        })
        .catch(function(){ showMsg('Network error — please try again.',false); })
        .then(function(){ btn.disabled=false; btn.textContent=old; });
    };
  }

  function makeBtn(){
    var b=document.createElement('button');
    b.id='mlsPortalInviteBtn'; b.type='button';
    b.textContent='Patient portal';
    b.setAttribute('aria-label','Open patient portal invite for the active patient');
    b.style.cssText='margin:0;display:inline-flex;align-items:center;justify-content:center;gap:6px;background:#EAF1EE;border:1px solid #C9DCD2;color:#204034;border-radius:9px;padding:5px 11px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;line-height:1.2;white-space:nowrap';
    b.addEventListener('mouseenter',function(){ b.style.background='#e2edfa'; });
    b.addEventListener('mouseleave',function(){ b.style.background='#EAF1EE'; });
    b.addEventListener('click',function(e){ e.preventDefault(); e.stopPropagation(); var ap=active(); if(!ap){ (window.toast||window.alert)('Select a patient first.','err'); return; } openModal(ap); });
    return b;
  }

  function inject(){
    try{
      var ap=active();
      var b=document.getElementById('mlsPortalInviteBtn');
      if(!ap){ if(b) b.remove(); return; } // only show for a real active patient

      /* b906: this button is INVISIBLE in the reworked patient banner — the
         bar's allowlist hides every child but the identity block and Recent —
         but it deliberately still MOUNTS, and that is not an oversight.
         feat_mls_patient_reach_v2's delegatePortalInvite() reaches for
         #mlsPortalInviteBtn by id and clicks it to open the secure invite;
         removing the node outright turns Patient Reach's own portal invite
         into "The secure portal invite is still loading." So the node stays as
         the mechanism and stops being furniture. The doctor-facing way in is
         "Send to your patients" -> Patient portal access. */

      if(!b) b=makeBtn();
      if(b.textContent!=='Patient portal') b.textContent='Patient portal';
      var title='Open the patient portal for '+String(ap.name||'this patient')+'. Nothing sends until you click Send login.';
      if(b.title!==title) b.title=title;

      /* The unified patient card may render after an early fallback button.
         Reconcile that existing node into the visible actions row instead of
         returning merely because its ID already exists. */
      var actions=document.querySelector('#mlsCtxBar .mlsctx-actions');
      if(actions){
        var switchBtn=actions.querySelector('button[data-act="switch"]')||actions.querySelector('.mlsctx-switch');
        if(b.parentNode!==actions || (switchBtn && b.nextSibling!==switchBtn)) actions.insertBefore(b,switchBtn||null);
        return;
      }

      var host=document.querySelector('.mlsctx-id')||document.querySelector('.mlsctx-idtext')||document.querySelector('#visitHero');
      var hero=document.getElementById('heroPtName');
      if(host){
        var meta=host.querySelector('.mlsctx-meta');
        var fallbackParent=(meta && meta.parentNode) ? meta.parentNode : host;
        if(b.parentNode!==fallbackParent){
          if(meta && meta.parentNode){ fallbackParent.insertBefore(b, meta.nextSibling); }
          else { fallbackParent.appendChild(b); }
        }
      } else if(hero && hero.parentNode){
        if(b.parentNode!==hero.parentNode) hero.parentNode.insertBefore(b, hero.nextSibling);
      } else { return; }
    }catch(e){}
  }

  var injectQueued=false;
  function scheduleInject(){
    if(injectQueued) return;
    injectQueued=true;
    (window.requestAnimationFrame||function(fn){return setTimeout(fn,16);})(function(){
      injectQueued=false; inject();
    });
  }
  /* Patient switches rebuild the header. Coalesce that mutation burst into one
     reinsertion pass instead of running a document-wide callback plus a
     permanent 1.5-second polling loop for the lifetime of the page. */
  try{ new MutationObserver(scheduleInject).observe(document.documentElement,{childList:true,subtree:true}); }catch(e){}
  if(document.readyState!=='loading') inject(); else document.addEventListener('DOMContentLoaded', inject);
})();


